import{_ as l,C as a,o as n,c as s,j as e,a as d,E as o,a5 as c}from"./chunks/framework.BYIUCCsM.js";const P=JSON.parse('{"title":"计时器","description":"","frontmatter":{},"headers":[],"relativePath":"components/timer.md","filePath":"components/timer.md","lastUpdated":1787359578000}'),h={name:"components/timer.md"},m={id:"计时器",tabindex:"-1"};function u(p,t,b,g,x,f){const i=a("Badge"),r=a("XhDemo");return n(),s("div",null,[e("h1",m,[t[0]||(t[0]=d("计时器 ",-1)),o(i,{type:"info",text:"timer"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#计时器","aria-label":'Permalink to "计时器 <Badge type="info" text="timer" />"'},"​",-1))]),t[3]||(t[3]=c('<p>一段可正可倒的计时：能起、能停、能接着走、能归零。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>秒表、答题计时、专注计时这类需要用户自己控制起停的场景。</li><li>会议或直播的已进行时长。</li><li>需要倒着走、并且要在中途暂停的限时任务。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只倒数、不需要任何控制：用<a href="./countdown">倒计时</a>，它更小，作者只给一个剩余时长。</li><li>展示的是一个时刻而不是一段时长：用<a href="./time">时间</a>。</li><li>表达任务完成到哪一步：用<a href="./progress">进度条</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>正着走还是倒着走由 <code>countdown</code> 决定，起点 <code>startMs</code> 与终点 <code>targetMs</code> 两个方向共用。</li><li><code>start</code> / <code>pause</code> / <code>resume</code> / <code>reset</code> 四个动作齐全，<code>control</code> 部件把它们收成一个按钮，按当前状态自动换语义。</li><li>时间只从单调时钟的两个时刻相减而来，一拍都不累加，所以停停走走也不会越走越偏。</li><li><code>interval</code> 只决定数字多久跳一次；到点由另一个精确落在终点上的定时器判定，终点不落在整拍上也不会走过头。</li><li>每一段数字是一个 <code>item</code> 部件，<code>unit</code> 说明它是天、时、分、秒还是毫秒，排版完全交给作者。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一个自己往上走的秒表：不写内容时组件铺开时、分、秒三段，auto-start 让它挂载即开跑</p>',10)),o(r,{src:"timer/01-basic"}),t[4]||(t[4]=e("h3",{id:"倒着走",tabindex:"-1"},[d("倒着走 "),e("a",{class:"header-anchor",href:"#倒着走","aria-label":'Permalink to "倒着走"'},"​")],-1)),t[5]||(t[5]=e("p",null,"countdown 让它从起始值往下走，终点缺省是 0；走到终点就停在那里不再往下",-1)),o(r,{src:"timer/02-countdown"}),t[6]||(t[6]=e("h3",{id:"起停与归零",tabindex:"-1"},[d("起停与归零 "),e("a",{class:"header-anchor",href:"#起停与归零","aria-label":'Permalink to "起停与归零"'},"​")],-1)),t[7]||(t[7]=e("p",null,"自己写部件：control 是一个原生按钮，按一下就按当前状态走一步（开始 / 暂停 / 继续 / 重来）",-1)),o(r,{src:"timer/03-control"}),t[8]||(t[8]=e("h3",{id:"带天数的长计时",tabindex:"-1"},[d("带天数的长计时 "),e("a",{class:"header-anchor",href:"#带天数的长计时","aria-label":'Permalink to "带天数的长计时"'},"​")],-1)),t[9]||(t[9]=e("p",null,"时满 24 会进位到天，超过一天的计时要自己写一段 days，只写时分秒会把整天数丢掉",-1)),o(r,{src:"timer/04-days"}),t[10]||(t[10]=e("h3",{id:"三个尺寸档",tabindex:"-1"},[d("三个尺寸档 "),e("a",{class:"header-anchor",href:"#三个尺寸档","aria-label":'Permalink to "三个尺寸档"'},"​")],-1)),t[11]||(t[11]=e("p",null,"size 只写在 root 上，数字大小与起停按钮的高度一起换档，子部件不重复标注",-1)),o(r,{src:"timer/05-size"}),t[12]||(t[12]=e("h3",{id:"每一拍与到点",tabindex:"-1"},[d("每一拍与到点 "),e("a",{class:"header-anchor",href:"#每一拍与到点","aria-label":'Permalink to "每一拍与到点"'},"​")],-1)),t[13]||(t[13]=e("p",null,"tick 每过一个 interval 发一次，complete 只在走到终点那一刻发一次；到点那一拍不再发 tick",-1)),o(r,{src:"timer/06-notify"}),t[14]||(t[14]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-timer&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTimerArea</code> <code>XhTimerControl</code> <code>XhTimerItem</code> <code>XhTimerRoot</code> <code>XhTimerSeparator</code></td></tr><tr><td>组合式函数</td><td><code>useTimer</code></td></tr><tr><td>状态机</td><td><code>timerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/timer.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;timer&quot;</code>：<strong><code>root</code></strong> · <strong><code>area</code></strong> · <code>item</code> · <code>separator</code> · <code>control</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>startMs</code></td><td><code>number</code></td><td></td><td>起始值毫秒，缺省 0。正计时从它往上走，倒计时从它往下走。</td></tr><tr><td><code>targetMs</code></td><td><code>number</code></td><td></td><td>终点值毫秒。倒计时缺省 0；正计时不给它就一直走下去，没有终点也不会通知走完。 终点落在起点的反方向（倒计时给了比起点还大的终点）时这一轮长度为 0： 显示值停在起点上，一开跑就到点。</td></tr><tr><td><code>countdown</code></td><td><code>boolean</code></td><td></td><td>倒着走，缺省假。</td></tr><tr><td><code>autoStart</code></td><td><code>boolean</code></td><td></td><td>挂载即开跑，缺省假。它只在挂载那一刻读一次，之后改它不再有作用。</td></tr><tr><td><code>interval</code></td><td><code>number</code></td><td></td><td>刷新间隔毫秒，缺省 1000，下限一帧。 它只决定数字多久跳一次；到点由另一个精确落在终点上的定时器判定，不受它影响。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TimerTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onTick</code></td><td><code>(details: TimerTickDetails) =&gt; void</code></td><td></td><td>每一拍通知一次。到点那一拍只发 onComplete。</td></tr><tr><td><code>onComplete</code></td><td><code>(details: TimerCompleteDetails) =&gt; void</code></td><td></td><td>走到终点通知一次；中途被暂停或归零不通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>tick</code></td><td><code>TimerTickDetails</code></td><td>走过一拍；detail 为 <code>{ value: number, elapsed: number }</code></td></tr><tr><td><code>complete</code></td><td><code>TimerCompleteDetails</code></td><td>走到终点；detail 为 <code>{ value: number, elapsed: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTimerRoot</code></td><td><code>default</code></td><td><code>TimerRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr><tr><td><code>area</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>running</code> · <code>paused</code> · <code>completed</code></p><p><strong>事件</strong>：<code>RUN.START</code> · <code>RUN.PAUSE</code> · <code>RUN.RESUME</code> · <code>RUN.RESET</code> · <code>CLOCK.TICK</code> · <code>CLOCK.SETTLE</code> · <code>CLOCK.SYNC</code></p><p><strong>判据</strong>：<code>isSettled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useTimer</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>TimerPhase</code></td><td></td></tr><tr><td><code>value</code></td><td><code>number</code></td><td>当前该显示的毫秒，已夹在起点与终点之间。</td></tr><tr><td><code>elapsed</code></td><td><code>number</code></td><td>累计走了多少毫秒，与方向和起始值无关。</td></tr><tr><td><code>running</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>paused</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>completed</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>countdown</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>segments</code></td><td><code>TimerSegments</code></td><td>显示值拆开的五段。</td></tr><tr><td><code>segmentText</code></td><td><code>(unit: TimerUnit) =&gt; string</code></td><td>某一段补零后的字面：天不补零，时分秒两位，毫秒三位。</td></tr><tr><td><code>controlAction</code></td><td><code>TimerControlAction</code></td><td>起停按钮这一下要做的事。</td></tr><tr><td><code>controlLabel</code></td><td><code>string</code></td><td>起停按钮的读屏名字，也是按钮里没写内容时该显示的字。</td></tr><tr><td><code>start</code></td><td><code>() =&gt; void</code></td><td>从头开跑。</td></tr><tr><td><code>pause</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>resume</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>reset</code></td><td><code>() =&gt; void</code></td><td>归零并停下。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getAreaProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: TimerItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on control</td><td>按当前状态起停：没起步的开跑、在走的暂停、停在半路的接着走、走完的归零；control 是原生 button，这两个键由平台翻成 click</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>area</code></td><td><code>aria-label</code></td><td>label.time(segments)</td></tr><tr><td><code>area</code></td><td><code>aria-live</code></td><td>&#39;off&#39;</td></tr><tr><td><code>area</code></td><td><code>role</code></td><td>&#39;timer&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>separator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>control</code></td><td><code>aria-label</code></td><td>label[controlAction]</td></tr></tbody></table><ul><li>时间区带着整段时间的读屏名字，里面的数字与记号对读屏是隐藏的。</li><li>内建的那个名字恒按「时 分 秒」念（天数大于 0 时前面再加一段天）。屏幕上只摆了其中几段（例如只有分和秒）时它会多念一段，请用 <code>translations.time</code> 自己按摆出来的段数给名字。</li><li>内建名字是英文，换语言同样走 <code>translations.time</code>。</li><li>要播报请自己在外层另起一个 live 区，只在关口上说一句：每秒都在变的数字按 polite 播报，一分钟就是六十条打断。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/timer.css</code> 按部件选择：<code>[data-scope=&quot;timer&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-countdown</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr><tr><td><code>area</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr><tr><td><code>item</code></td><td><code>data-unit</code></td><td>item.unit</td></tr><tr><td><code>control</code></td><td><code>data-action</code></td><td>&#39;pause&#39; | &#39;resume&#39; | &#39;reset&#39; | &#39;start&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-timer-area-fg</code> · <code>--xh-timer-completed-fg</code> · <code>--xh-timer-control-bg</code> · <code>--xh-timer-control-bg-active</code> · <code>--xh-timer-control-bg-disabled</code> · <code>--xh-timer-control-bg-hover</code> · <code>--xh-timer-control-border</code> · <code>--xh-timer-control-border-disabled</code> · <code>--xh-timer-control-border-focus</code> · <code>--xh-timer-control-border-hover</code> · <code>--xh-timer-control-fg</code> · <code>--xh-timer-control-gap</code> · <code>--xh-timer-control-h</code> · <code>--xh-timer-control-px</code> · <code>--xh-timer-control-radius</code> · <code>--xh-timer-digit-font-size</code> · <code>--xh-timer-fg</code> · <code>--xh-timer-gap</code> · <code>--xh-timer-separator-fg</code> · <code>--xh-timer-separator-px</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>时间区的排列方向钉成从左到右，<code>&lt;html dir=&quot;rtl&quot;&gt;</code> 下时分秒不会倒过来排——时间串的读序两个方向都一样。</li><li>起停按钮相对时间区的位置、以及整个组件在页面里的排布，照常跟随文字方向。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./button">按钮</a>配合做「开始 / 暂停 / 重来」一排控制。</li><li>与<a href="./progress">进度条</a>并排，一个说还剩多久、一个说走了几成。</li><li>走完后用<a href="./alert">警告提示</a>或<a href="./toast">提示消息</a>告诉用户下一步做什么。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>计时超过一天要自己加一段 <code>days</code>：<code>hours</code> 满 24 会进位到天，只写时分秒会把整天数丢掉。</li><li>数字用等宽字形，位数变化时分隔符才不会左右挪动，皮肤已经这样做了，自定义排版时别丢掉。</li><li>每一段的数字恒由组件写进条目里，作者只声明这一段是哪个单位；写在条目里的内容留不住，下一拍就会被新的数字盖掉。要在数字旁边加字（「时」「分」）请写进记号部件。</li><li>起停按钮的名字（读屏念的那个）恒由组件按当前状态给，换语言走 <code>translations</code>，别硬编码。按钮里显示的那行字两个适配器不一样，见下一条。</li><li>两个适配器的差别只有三处，写标记前先对一眼： <ul><li><strong>默认结构</strong>：Vue 的根组件不写内容时会自动铺开「时:分:秒」；Web Components 侧元素不生成任何结构，root 与 area 一个都不能少，每一段与记号都要作者自己写出来。</li><li><strong>按钮里的字</strong>：Vue 的起停按钮不写内容时填当前动作的名字（Start / Pause / Resume / Reset）；Web Components 侧那行字归作者写（按钮里多半是个图标），元素只换按钮的 <code>data-action</code> 与读屏名字。</li><li><strong>记号的缺省</strong>：Vue 的记号部件不写内容时是一个冒号；Web Components 侧记号里的字一律归作者写。</li></ul></li><li>Web Components 侧条目上的 <code>unit</code> 是作者的声明、不是元素写回的状态，改它本身不会另排一次接线：停着的时候改完要等下一次属性变更或起跑才生效（跑起来时每一拍都会重接一次，自然跟上）。</li><li>走完之后要有明确的去处：或者归零重来，或者跳去下一步，别停在 00:00 就不动了。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用它显示当前时刻：它只认时长，不认日历也不认时区。</li><li>只给终点不给起点做倒计时：起点缺省是 0，倒着走会一开跑就到点，屏幕上恒是 00:00。要倒计多久写进 <code>startMs</code>。</li><li>挂载后再改 <code>autoStart</code> 指望它开跑：那个 prop 只在挂载那一刻读一次，起停请用动作或 <code>control</code>。</li><li>走完了不发生任何事，用户白等一场。</li></ul>',50))])}const T=l(h,[["render",u]]);export{P as __pageData,T as default};
